module.exports = nextConfig;

{
  "name": "SocialFlow AI - Content Generator API",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "socialflow-generate",
        "responseMode": "responseNode",
        "options": {}
      },
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 2,
      "position": [-640, 0],
      "id": "webhook-trigger-001",
      "name": "Webhook Trigger",
      "webhookId": "socialflow-generate"
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "norm-url",
              "name": "websiteUrl",
              "value": "={{ $json.body.websiteUrl || $json.body.url || '' }}",
              "type": "string"
            },
            {
