  },
  "tags": ["socialflow", "saas", "api"]
}

:root {
  --bg: #0a0a0f;
  --bg-elevated: #12121a;
  --bg-card: #16161f;
  --border: #2a2a3a;
  --text: #f4f4f8;
  --text-muted: #9898b0;
  --accent: #6366f1;
  --accent-hover: #818cf8;
  --success: #22c55e;
  --error: #ef4444;
  --gradient: linear-gradient(135deg, #6366f1 0%, #a855f7 50%, #ec4899 100%);
  --shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  --radius: 12px;
  --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
}

[data-theme='light'] {
  --bg: #f8f9fc;
  --bg-elevated: #ffffff;
  --bg-card: #ffffff;
  --border: #e2e4ec;
  --text: #0f0f14;
  --text-muted: #5c5c70;
  --shadow: 0 8px 32px rgba(15, 15, 20, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  color: var(--accent-hover);
}

.container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.9rem;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-primary {
  background: var(--gradient);
  color: white;
}

.btn-primary:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
}

.btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}

.btn-ghost:hover {
  background: var(--bg-elevated);
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
}

.input,
.textarea,
.select {
  width: 100%;
  padding: 0.75rem 1rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.95rem;
  font-family: inherit;
  transition: border-color 0.2s;
}

.input:focus,
.textarea:focus,
.select:focus {
  outline: none;
  border-color: var(--accent);
}

.textarea {
  min-height: 120px;
  resize: vertical;
}

.label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
  color: var(--text-muted);
}

.field {
  margin-bottom: 1.25rem;
}

.spinner {
  width: 20px;
  height: 20px;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.skeleton {
  background: linear-gradient(
    90deg,
    var(--bg-elevated) 25%,
    var(--border) 50%,
    var(--bg-elevated) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
  border-radius: 6px;
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@media (max-width: 768px) {
  .hide-mobile {
    display: none !important;
  }
}

import type { Metadata } from 'next';
import { ClerkProvider } from '@clerk/nextjs';
import { Toaster } from 'sonner';
import { ThemeProvider } from '@/components/ThemeProvider';
import { Header } from '@/components/Header';
import './globals.css';

export const metadata: Metadata = {
  title: 'SocialFlow AI — Social Media Content from Any URL',
  description:
    'AI-powered SaaS that turns website content into platform-optimized social posts using Firecrawl and n8n.',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <ClerkProvider>
      <html lang="en" data-theme="dark">
        <body>
          <ThemeProvider>
            <Header />
            <main>{children}</main>
            <Toaster richColors position="top-right" theme="system" />
          </ThemeProvider>
        </body>
      </html>
    </ClerkProvider>
  );
}

export const dynamic = 'force-dynamic';

import { Hero } from '@/components/Hero';
import { ProductFeatures } from '@/components/ProductFeatures';
import { GenerateForm } from '@/components/GenerateForm';

export default function HomePage() {
  return (
    <>
      <Hero />
      <GenerateForm />
      <ProductFeatures />
      <footer
        style={{
          borderTop: '1px solid var(--border)',
          padding: '2rem 0',
          textAlign: 'center',
          color: 'var(--text-muted)',
          fontSize: '0.85rem',
        }}
      >
        <div className="container">
          SocialFlow AI — Powered by Firecrawl, n8n, and Next.js
        </div>
      </footer>
    </>
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth } from '@/lib/auth';
import { scrapeWebsite } from '@/lib/firecrawl';
import { crawlPreviewSchema } from '@/lib/validations';
import { checkRateLimit } from '@/lib/rate-limit';
import { cacheGet, cacheSet } from '@/lib/redis';
import { sanitizeUrl } from '@/lib/sanitize';
import crypto from 'crypto';

export async function POST(req: NextRequest) {
  try {
    const userId = await requireAuth();
    const body = await req.json();
    const parsed = crawlPreviewSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const rate = await checkRateLimit(`crawl:${userId}`);
    if (!rate.allowed) {
      return NextResponse.json(
        { error: 'Rate limit exceeded. Try again later.' },
        { status: 429, headers: { 'Retry-After': String(Math.ceil(rate.resetMs / 1000)) } }
      );
    }

    const url = sanitizeUrl(parsed.data.websiteUrl);
    const cacheKey = `crawl:${crypto.createHash('sha256').update(url).digest('hex')}`;

    const cached = await cacheGet<{ markdown: string; title?: string; description?: string }>(cacheKey);
    if (cached) {
      return NextResponse.json({ ...cached, sourceUrl: url, cached: true });
    }

    const scraped = await scrapeWebsite(url);
    await cacheSet(cacheKey, scraped, 1800);

    return NextResponse.json({
      markdown: scraped.markdown.slice(0, 2000),
      fullLength: scraped.markdown.length,
      title: scraped.title,
      description: scraped.description,
      sourceUrl: scraped.sourceUrl,
      cached: false,
    });
  } catch (err) {
    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    const message = err instanceof Error ? err.message : 'Crawl failed';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import { requireAuth, getAuthUser } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { scrapeWebsite } from '@/lib/firecrawl';
import { triggerN8nWorkflow } from '@/lib/n8n';
import { generateRequestSchema } from '@/lib/validations';
import { optimizePromptForPlatform, type PlatformId } from '@/lib/platforms';
import { checkRateLimit } from '@/lib/rate-limit';
import { sanitizeUrl } from '@/lib/sanitize';
import { GeneratedPost } from '@/models/GeneratedPost';
import { PromptHistory } from '@/models/PromptHistory';
import { WorkflowExecution } from '@/models/WorkflowExecution';
import {
  ensureUser,
  deductCredit,
  trackUsage,
} from '@/lib/user-service';
import { enqueueGeneration } from '@/lib/queue';

export const maxDuration = 120;

export async function POST(req: NextRequest) {
  const start = Date.now();
  let executionId = uuidv4();

  try {
    const userId = await requireAuth();
    const authUser = await getAuthUser();
    const body = await req.json();
    const parsed = generateRequestSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: parsed.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const rate = await checkRateLimit(`generate:${userId}`);
    if (!rate.allowed) {
      return NextResponse.json(
        { error: 'Rate limit exceeded. Upgrade or wait before generating more content.' },
        { status: 429 }
      );
    }

    await connectDB();
    await ensureUser({
      clerkId: userId,
      email: authUser?.email ?? '',
      name: authUser?.name ?? 'User',
      imageUrl: authUser?.imageUrl,
    });

    const hasCredit = await deductCredit(userId, 1);
    if (!hasCredit) {
      return NextResponse.json(
        { error: 'Insufficient credits. Please upgrade your plan.' },
        { status: 402 }
      );
    }

    const { websiteUrl, userPrompt, platform } = parsed.data;
    const safeUrl = sanitizeUrl(websiteUrl);
    const optimizedPrompt = optimizePromptForPlatform(
      userPrompt,
      platform as PlatformId
    );
    executionId = uuidv4();

    await WorkflowExecution.create({
      userId,
      executionId,
      status: 'running',
      input: { websiteUrl: safeUrl, userPrompt, platform },
    });

    await GeneratedPost.create({
      userId,
      executionId,
      websiteUrl: safeUrl,
      userPrompt,
      platform,
      status: 'pending',
      content: '',
    });

    await PromptHistory.create({
      userId,
      websiteUrl: safeUrl,
      userPrompt,
      platform,
      optimizedPrompt,
    });

    const useQueue = process.env.USE_QUEUE === 'true';
    if (useQueue) {
      const scraped = await scrapeWebsite(safeUrl);
      const queued = await enqueueGeneration({
        userId,
        executionId,
        websiteUrl: safeUrl,
        scrapedContent: scraped.markdown,
        userPrompt,
        optimizedPrompt,
        platform,
      });

      if (queued.queued) {
        return NextResponse.json({
          status: 'queued',
          executionId,
          jobId: queued.jobId,
          message: 'Generation queued. Poll /api/history for results.',
        });
      }
    }

    const scraped = await scrapeWebsite(safeUrl);
    const result = await triggerN8nWorkflow({
      websiteUrl: safeUrl,
      scrapedContent: scraped.markdown,
      userPrompt,
      optimizedPrompt,
      platform: platform as PlatformId,
      userId,
      executionId,
    });

    const durationMs = Date.now() - start;

    await GeneratedPost.findOneAndUpdate(
      { executionId },
      {
        status: 'completed',
        content: result.content ?? '',
        summary: result.summary,
        qualityScore: result.qualityScore,
        wordCount: result.wordCount,
      }
    );

    await WorkflowExecution.findOneAndUpdate(
      { executionId },
      {
        status: 'completed',
        output: result,
        durationMs,
      }
    );

    await trackUsage(userId, platform, 1);

    return NextResponse.json({
      status: 'completed',
      executionId,
      platform: result.platform,
      platformName: result.platformName,
      websiteUrl: result.websiteUrl ?? safeUrl,
      summary: result.summary,
      content: result.content,
      qualityScore: result.qualityScore,
      wordCount: result.wordCount,
      generatedAt: result.generatedAt,
      preview: {
        title: scraped.title,
        description: scraped.description,
      },
      durationMs,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Generation failed';

    if (executionId) {
      await connectDB().catch(() => {});
      await GeneratedPost.findOneAndUpdate(
        { executionId },
        { status: 'failed', error: message }
      ).catch(() => {});
      await WorkflowExecution.findOneAndUpdate(
        { executionId },
        { status: 'failed', error: message }
      ).catch(() => {});
    }

    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    return NextResponse.json({ error: message, executionId }, { status: 500 });
  }
}

