import { NextRequest, NextResponse } from 'next/server';
import { requireAuth } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { GeneratedPost } from '@/models/GeneratedPost';
import { PromptHistory } from '@/models/PromptHistory';

export async function GET(req: NextRequest) {
  try {
    const userId = await requireAuth();
    await connectDB();

    const { searchParams } = new URL(req.url);
    const type = searchParams.get('type') ?? 'posts';
    const limit = Math.min(Number(searchParams.get('limit') ?? 20), 50);
    const page = Math.max(Number(searchParams.get('page') ?? 1), 1);
    const skip = (page - 1) * limit;

    if (type === 'prompts') {
      const prompts = await PromptHistory.find({ userId })
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(limit)
        .lean();

      const total = await PromptHistory.countDocuments({ userId });
      return NextResponse.json({ prompts, total, page, limit });
    }

    const posts = await GeneratedPost.find({ userId })
      .sort({ createdAt: -1 })
      .skip(skip)
      .limit(limit)
      .lean();

    const total = await GeneratedPost.countDocuments({ userId });

    return NextResponse.json({ posts, total, page, limit });
  } catch (err) {
    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    return NextResponse.json({ error: 'Failed to fetch history' }, { status: 500 });
  }
}

import { NextRequest } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import { requireAuth } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { scrapeWebsite } from '@/lib/firecrawl';
import { triggerN8nWorkflow } from '@/lib/n8n';
import { generateRequestSchema } from '@/lib/validations';
import { optimizePromptForPlatform, type PlatformId } from '@/lib/platforms';
import { checkRateLimit } from '@/lib/rate-limit';
import { sanitizeUrl } from '@/lib/sanitize';
import { GeneratedPost } from '@/models/GeneratedPost';
import { deductCredit, trackUsage, ensureUser } from '@/lib/user-service';
import { getAuthUser } from '@/lib/auth';

export const maxDuration = 120;

function sse(data: Record<string, unknown>): string {
  return `data: ${JSON.stringify(data)}\n\n`;
}

export async function POST(req: NextRequest) {
  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    async start(controller) {
      const send = (payload: Record<string, unknown>) => {
        controller.enqueue(encoder.encode(sse(payload)));
      };

      try {
        const userId = await requireAuth();
        const authUser = await getAuthUser();
        const body = await req.json();
        const parsed = generateRequestSchema.safeParse(body);

        if (!parsed.success) {
          send({ type: 'error', message: 'Validation failed' });
          controller.close();
          return;
        }

        const rate = await checkRateLimit(`generate:${userId}`);
        if (!rate.allowed) {
          send({ type: 'error', message: 'Rate limit exceeded' });
          controller.close();
          return;
        }

        await connectDB();
        await ensureUser({
          clerkId: userId,
          email: authUser?.email ?? '',
          name: authUser?.name ?? 'User',
        });

        const hasCredit = await deductCredit(userId, 1);
        if (!hasCredit) {
          send({ type: 'error', message: 'Insufficient credits' });
          controller.close();
          return;
        }

        const executionId = uuidv4();
        const { websiteUrl, userPrompt, platform } = parsed.data;
        const safeUrl = sanitizeUrl(websiteUrl);
        const optimizedPrompt = optimizePromptForPlatform(
          userPrompt,
          platform as PlatformId
        );

        send({ type: 'status', message: 'Crawling website...', executionId });

        const scraped = await scrapeWebsite(safeUrl);
        send({
          type: 'preview',
          title: scraped.title,
          description: scraped.description,
          excerpt: scraped.markdown.slice(0, 500),
        });

        send({ type: 'status', message: 'Generating AI content...' });

        const result = await triggerN8nWorkflow({
          websiteUrl: safeUrl,
          scrapedContent: scraped.markdown,
          userPrompt,
          optimizedPrompt,
          platform: platform as PlatformId,
          userId,
          executionId,
        });

        await GeneratedPost.create({
          userId,
          executionId,
          websiteUrl: safeUrl,
          userPrompt,
          platform,
          status: 'completed',
          content: result.content ?? '',
          summary: result.summary,
          qualityScore: result.qualityScore,
          wordCount: result.wordCount,
        });

        await trackUsage(userId, platform, 1);

        send({
          type: 'complete',
          executionId,
          content: result.content,
          summary: result.summary,
          qualityScore: result.qualityScore,
          wordCount: result.wordCount,
          platform: result.platformName,
        });
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Stream failed';
        send({ type: 'error', message });
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    },
  });
}

import { NextResponse } from 'next/server';
import { requireAuth } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { User, type IUser } from '@/models/User';
import { UsageAnalytics } from '@/models/UsageAnalytics';
import { GeneratedPost } from '@/models/GeneratedPost';
import { WorkflowExecution } from '@/models/WorkflowExecution';

export async function GET() {
  try {
    const userId = await requireAuth();
    await connectDB();

    const user = await User.findOne({ clerkId: userId }).lean<IUser>();
    const analytics = await UsageAnalytics.find({ userId })
      .sort({ date: -1 })
      .limit(30)
      .lean();

    const totalPosts = await GeneratedPost.countDocuments({ userId });
    const completedExecutions = await WorkflowExecution.countDocuments({
      userId,
      status: 'completed',
    });
    const failedExecutions = await WorkflowExecution.countDocuments({
      userId,
      status: 'failed',
    });

    const platformBreakdown = await GeneratedPost.aggregate([
      { $match: { userId } },
      { $group: { _id: '$platform', count: { $sum: 1 } } },
      { $sort: { count: -1 } },
    ]);

    return NextResponse.json({
      user: {
        credits: user?.credits ?? 0,
        plan: user?.plan ?? 'free',
        name: user?.name,
      },
      stats: {
        totalPosts,
        completedExecutions,
        failedExecutions,
      },
      analytics,
      platformBreakdown: platformBreakdown.map((p) => ({
        platform: p._id,
        count: p.count,
      })),
    });
  } catch (err) {
    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    return NextResponse.json({ error: 'Failed to fetch usage' }, { status: 500 });
  }
}

