import { Queue, Worker, Job } from 'bullmq';
import { getRedis } from './redis';

const QUEUE_NAME = 'socialflow-generate';

export interface QueueJobData {
  userId: string;
  executionId: string;
  websiteUrl: string;
  scrapedContent: string;
  userPrompt: string;
  optimizedPrompt: string;
  platform: string;
}

let queue: Queue<QueueJobData> | null = null;

export function getGenerateQueue(): Queue<QueueJobData> | null {
  const redis = getRedis();
  if (!redis) return null;

  if (!queue) {
    queue = new Queue<QueueJobData>(QUEUE_NAME, {
      connection: { host: redis.options.host, port: redis.options.port },
    });
  }
  return queue;
}

export async function enqueueGeneration(
  data: QueueJobData
): Promise<{ queued: boolean; jobId?: string }> {
  const q = getGenerateQueue();
  if (!q) return { queued: false };

  const job = await q.add('generate', data, {
    attempts: 3,
    backoff: { type: 'exponential', delay: 2000 },
    removeOnComplete: 100,
    removeOnFail: 50,
  });

  return { queued: true, jobId: job.id };
}

export type JobProcessor = (job: Job<QueueJobData>) => Promise<void>;

export function startWorker(processor: JobProcessor): Worker<QueueJobData> | null {
  const redis = getRedis();
  if (!redis) return null;

  return new Worker<QueueJobData>(QUEUE_NAME, processor, {
    connection: { host: redis.options.host, port: redis.options.port },
    concurrency: 2,
  });
}

import { connectDB } from './db';
import mongoose from 'mongoose';

interface RateLimitDoc {
  key: string;
  count: number;
  windowStart: Date;
}

const RateLimitSchema = new mongoose.Schema<RateLimitDoc>({
  key: { type: String, required: true, unique: true },
  count: { type: Number, default: 0 },
  windowStart: { type: Date, default: Date.now },
});

const RateLimitModel =
  mongoose.models.RateLimit ??
  mongoose.model<RateLimitDoc>('RateLimit', RateLimitSchema);

export async function checkRateLimit(
  key: string
): Promise<{ allowed: boolean; remaining: number; resetMs: number }> {
  await connectDB();

  const points = Number(process.env.RATE_LIMIT_POINTS ?? 10);
  const durationSec = Number(process.env.RATE_LIMIT_DURATION_SEC ?? 3600);
  const windowMs = durationSec * 1000;
  const now = new Date();

  let doc = await RateLimitModel.findOne({ key });

  if (!doc || now.getTime() - doc.windowStart.getTime() > windowMs) {
    doc = await RateLimitModel.findOneAndUpdate(
      { key },
      { count: 1, windowStart: now },
      { upsert: true, new: true }
    );
    return { allowed: true, remaining: points - 1, resetMs: windowMs };
  }

  if (doc.count >= points) {
    const resetMs =
      windowMs - (now.getTime() - doc.windowStart.getTime());
    return { allowed: false, remaining: 0, resetMs: Math.max(resetMs, 0) };
  }

  doc = await RateLimitModel.findOneAndUpdate(
    { key },
    { $inc: { count: 1 } },
    { new: true }
  );

  return {
    allowed: true,
    remaining: points - (doc?.count ?? 1),
    resetMs: windowMs - (now.getTime() - (doc?.windowStart.getTime() ?? 0)),
  };
}

import Redis from 'ioredis';

let redis: Redis | null = null;

export function getRedis(): Redis | null {
  const url = process.env.REDIS_URL;
  if (!url) return null;

  if (!redis) {
    redis = new Redis(url, {
      maxRetriesPerRequest: 3,
      lazyConnect: true,
    });
  }
  return redis;
}

export async function cacheGet<T>(key: string): Promise<T | null> {
  const r = getRedis();
  if (!r) return null;
  try {
    const val = await r.get(key);
    return val ? (JSON.parse(val) as T) : null;
  } catch {
    return null;
  }
}

export async function cacheSet(
  key: string,
  value: unknown,
  ttlSeconds = 3600
): Promise<void> {
  const r = getRedis();
  if (!r) return;
  try {
    await r.setex(key, ttlSeconds, JSON.stringify(value));
  } catch {
    // cache is optional
  }
}

export function sanitizeText(input: string, maxLength = 50000): string {
  return input
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<[^>]+>/g, '')
    .trim()
    .slice(0, maxLength);
}

export function sanitizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      throw new Error('Invalid protocol');
    }
    return parsed.toString();
  } catch {
    throw new Error('Invalid URL');
  }
}

